CREATE OR REPLACE FUNCTION public.enforce_one_booking_per_customer_day()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_day DATE;
BEGIN
  IF NEW.status NOT IN ('pending', 'confirmed', 'payment_needed') THEN
    RETURN NEW;
  END IF;

  SELECT (s.start_time AT TIME ZONE 'UTC')::DATE INTO v_day
  FROM sessions s WHERE s.id = NEW.session_id;

  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.customer_id::TEXT || v_day::TEXT, 0));

  IF EXISTS (
    SELECT 1
    FROM bookings b
    JOIN sessions s ON s.id = b.session_id
    WHERE b.customer_id = NEW.customer_id
      AND b.id <> NEW.id
      AND b.status IN ('pending', 'confirmed', 'payment_needed')
      AND (s.start_time AT TIME ZONE 'UTC')::DATE = v_day
  ) THEN
    RAISE EXCEPTION 'This customer already has a booking on %. Only one booking per customer per day is allowed.',
      to_char(v_day, 'DD Mon YYYY');
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.event_booking_block_reason(p_event_id uuid, p_customer_id uuid, p_new_membership_frequency text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  e public.events%ROWTYPE;
  v_now timestamp := now() AT TIME ZONE 'Europe/London';
  v_member boolean := public.event_member_level_with_new(p_customer_id, p_new_membership_frequency) IS NOT NULL;
BEGIN
  SELECT * INTO e FROM public.events WHERE id = p_event_id;
  IF NOT FOUND THEN RETURN 'event_not_found'; END IF;
  IF e.cancelled_at IS NOT NULL THEN RETURN 'event_cancelled'; END IF;
  IF NOT e.active THEN RETURN 'event_not_on_sale'; END IF;
  IF (e.starts_at AT TIME ZONE 'UTC') <= v_now THEN RETURN 'event_started'; END IF;
  IF e.access = 'members_only' AND NOT v_member THEN RETURN 'event_members_only'; END IF;
  IF e.access = 'members_first' AND NOT v_member AND (e.public_release_at AT TIME ZONE 'UTC') > v_now THEN
    RETURN 'event_not_released_yet';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.event_cancellation_quote(p_event_booking_id uuid, p_attendee_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  b record;
  v_line_total numeric := 0;
  v_line_discount numeric := 0;
  v_net_line numeric;
  v_cancelled_value numeric;
  v_remaining_value numeric;
  v_remaining_count int;
  v_remaining_units numeric;
  v_sel_count int;
  v_sel_units numeric;
  v_sel_ids uuid[];
  v_value numeric;
  v_now_london timestamp := (now() AT TIME ZONE 'Europe/London');
BEGIN
  SELECT eb.id, eb.status, eb.event_id, eb.customer_id, e.refund_cutoff_at, e.starts_at, e.ends_at,
         e.cancelled_at AS event_cancelled_at
  INTO b
  FROM public.event_bookings eb JOIN public.events e ON e.id = eb.event_id
  WHERE eb.id = p_event_booking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'booking_not_found'); END IF;
  IF b.status <> 'confirmed' THEN RETURN jsonb_build_object('ok', false, 'reason', 'booking_not_confirmed'); END IF;

  SELECT COALESCE(SUM(oli.line_total), 0), COALESCE(SUM(oli.discount_amount), 0)
  INTO v_line_total, v_line_discount
  FROM public.order_line_items oli
  WHERE oli.event_booking_id = p_event_booking_id AND oli.item_type = 'event';
  v_net_line := GREATEST(v_line_total - v_line_discount, 0);

  SELECT COALESCE(SUM(cancelled_value), 0) INTO v_cancelled_value
  FROM public.event_attendees WHERE event_booking_id = p_event_booking_id AND cancelled_at IS NOT NULL;
  v_remaining_value := GREATEST(v_net_line - v_cancelled_value, 0);

  SELECT COUNT(*), COALESCE(SUM(unit_price), 0) INTO v_remaining_count, v_remaining_units
  FROM public.event_attendees WHERE event_booking_id = p_event_booking_id AND cancelled_at IS NULL;

  IF p_attendee_ids IS NULL THEN
    SELECT array_agg(id) INTO v_sel_ids FROM public.event_attendees
    WHERE event_booking_id = p_event_booking_id AND cancelled_at IS NULL;
  ELSE
    SELECT array_agg(DISTINCT x) INTO v_sel_ids FROM unnest(p_attendee_ids) x;
    IF EXISTS (SELECT 1 FROM unnest(v_sel_ids) x
               WHERE NOT EXISTS (SELECT 1 FROM public.event_attendees ea WHERE ea.id = x AND ea.event_booking_id = p_event_booking_id)) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'attendee_not_found');
    END IF;
    IF EXISTS (SELECT 1 FROM public.event_attendees WHERE id = ANY(v_sel_ids) AND cancelled_at IS NOT NULL) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_cancelled');
    END IF;
  END IF;
  IF v_sel_ids IS NULL OR cardinality(v_sel_ids) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'nothing_to_cancel');
  END IF;
  IF EXISTS (SELECT 1 FROM public.event_attendees WHERE id = ANY(v_sel_ids) AND checked_in_at IS NOT NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'attendee_checked_in');
  END IF;

  SELECT COUNT(*), COALESCE(SUM(unit_price), 0) INTO v_sel_count, v_sel_units
  FROM public.event_attendees WHERE id = ANY(v_sel_ids);

  IF v_sel_count = v_remaining_count THEN
    v_value := v_remaining_value;  -- the last places take whatever is left, so rounding never drifts
  ELSIF v_remaining_units > 0 THEN
    v_value := LEAST(ROUND(v_remaining_value * v_sel_units / v_remaining_units, 2), v_remaining_value);
  ELSE
    v_value := 0;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'event_id', b.event_id,
    'customer_id', b.customer_id,
    'attendee_ids', to_jsonb(v_sel_ids),
    'places', v_sel_count,
    'whole_booking', v_sel_count = v_remaining_count,
    'value', v_value,
    'refund_cutoff_at', b.refund_cutoff_at,
    'before_cutoff', b.refund_cutoff_at IS NOT NULL AND v_now_london < (b.refund_cutoff_at AT TIME ZONE 'UTC'),
    'event_started', b.starts_at IS NOT NULL AND v_now_london >= (b.starts_at AT TIME ZONE 'UTC'),
    'event_cancelled', b.event_cancelled_at IS NOT NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_upcoming_sessions(horizon_days integer DEFAULT 98)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_edge date; v_target date; v_inserted int;
begin
  v_target := (now() at time zone 'Europe/London')::date + horizon_days;
  select coalesce(max(start_time)::date, (now() at time zone 'Europe/London')::date - 1)
    into v_edge from sessions;
  if v_edge >= v_target then return 0; end if;

  insert into sessions (service_type_id, start_time, end_time, type, capacity, status)
  select svc.id, (d.day + sl.start_time),
         (d.day + sl.start_time) + (svc.duration || ' minutes')::interval,
         svc.booking_type, svc.capacity, 'open'
  from generate_series((v_edge + 1)::timestamp, v_target::timestamp, interval '1 day') as g(day_ts)
  cross join lateral (select g.day_ts::date as day) d
  join service_type_schedule_slots sl on sl.day_of_week = extract(dow from d.day)::smallint
  join service_types svc on svc.id = sl.service_type_id
  where svc.active and svc.duration is not null and svc.duration > 0 and svc.booking_type is not null
  on conflict (service_type_id, start_time) do nothing;

  get diagnostics v_inserted = row_count;
  return v_inserted;
end $function$

CREATE OR REPLACE FUNCTION public.membership_mark_cancelled_by_stripe(p_stripe_subscription_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m customer_memberships%ROWTYPE; covered date; today date := (now() AT TIME ZONE 'Europe/London')::date; flagged integer;
BEGIN
  SELECT * INTO m FROM customer_memberships WHERE stripe_subscription_id = p_stripe_subscription_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  -- Involuntary end (was past_due) or Stripe-side cancel: access ends today unless an end date was already set.
  covered := COALESCE(m.cancel_effective_date,
                      CASE WHEN m.subscription_status = 'past_due'
                           THEN (SELECT COALESCE(max(period_end), today - 1) FROM membership_credit_periods WHERE membership_id = m.id)
                           ELSE today END);
  UPDATE customer_memberships
  SET subscription_status = 'cancelled',
      cancel_effective_date = COALESCE(cancel_effective_date, covered),
      updated_at = now()
  WHERE id = m.id;
  flagged := public.flag_uncovered_credit_bookings(m.id, covered);
  RETURN jsonb_build_object('found', true, 'action', 'cancelled', 'covered_through', covered, 'bookings_flagged', flagged);
END $function$

CREATE OR REPLACE FUNCTION public.membership_mark_paid(p_stripe_subscription_id text, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m customer_memberships%ROWTYPE; restored integer := 0; periods integer;
BEGIN
  SELECT * INTO m FROM customer_memberships WHERE stripe_subscription_id = p_stripe_subscription_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  IF m.subscription_status = 'cancelled' THEN
    RETURN jsonb_build_object('found', true, 'action', 'ignored_cancelled');
  END IF;
  UPDATE customer_memberships
  SET subscription_status = 'active',
      next_renewal_date = COALESCE((p_period_end AT TIME ZONE 'Europe/London')::date, next_renewal_date),
      updated_at = now()
  WHERE id = m.id;
  WITH r AS (
    UPDATE bookings SET status = 'confirmed', payment_due_by = NULL, updated_at = now()
    WHERE redeemed_membership_id = m.id AND redemption_source = 'membership_credit' AND status = 'payment_needed'
    RETURNING 1)
  SELECT count(*) INTO restored FROM r;
  SELECT public.allocate_membership_credit_periods() INTO periods;
  RETURN jsonb_build_object('found', true, 'action', 'reactivated', 'was', m.subscription_status,
                            'bookings_restored', restored, 'periods_created', periods);
END $function$

CREATE OR REPLACE FUNCTION public.membership_mark_payment_failed(p_stripe_subscription_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m customer_memberships%ROWTYPE; covered date; flagged integer;
BEGIN
  SELECT * INTO m FROM customer_memberships WHERE stripe_subscription_id = p_stripe_subscription_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  IF m.subscription_status = 'cancelled' THEN
    RETURN jsonb_build_object('found', true, 'action', 'ignored_cancelled');
  END IF;
  UPDATE customer_memberships SET subscription_status = 'past_due', updated_at = now() WHERE id = m.id;
  SELECT COALESCE(max(period_end), (now() AT TIME ZONE 'Europe/London')::date - 1) INTO covered
  FROM membership_credit_periods WHERE membership_id = m.id;
  flagged := public.flag_uncovered_credit_bookings(m.id, covered);
  RETURN jsonb_build_object('found', true, 'action', 'past_due', 'covered_through', covered, 'bookings_flagged', flagged);
END $function$

CREATE OR REPLACE FUNCTION public.membership_period_for(p_anchor date, p_day date)
 RETURNS TABLE(period_start date, period_end date)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  n INTEGER;
BEGIN
  IF p_day < p_anchor THEN
    RETURN;
  END IF;
  n := (EXTRACT(YEAR FROM p_day)::INTEGER - EXTRACT(YEAR FROM p_anchor)::INTEGER) * 12
     + (EXTRACT(MONTH FROM p_day)::INTEGER - EXTRACT(MONTH FROM p_anchor)::INTEGER);
  WHILE (p_anchor + make_interval(months => n))::DATE > p_day LOOP
    n := n - 1;
  END LOOP;
  WHILE (p_anchor + make_interval(months => n + 1))::DATE <= p_day LOOP
    n := n + 1;
  END LOOP;
  period_start := (p_anchor + make_interval(months => n))::DATE;
  period_end   := (p_anchor + make_interval(months => n + 1))::DATE - 1;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.membership_sync_cancel_at_period_end(p_stripe_subscription_id text, p_cancel_at_period_end boolean, p_cancel_at timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m customer_memberships%ROWTYPE; new_date date;
BEGIN
  SELECT * INTO m FROM customer_memberships WHERE stripe_subscription_id = p_stripe_subscription_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  IF m.subscription_status = 'cancelled' THEN
    RETURN jsonb_build_object('found', true, 'action', 'ignored_cancelled');
  END IF;

  IF p_cancel_at IS NOT NULL THEN
    new_date := (p_cancel_at AT TIME ZONE 'Europe/London')::date - 1;
  ELSIF p_cancel_at_period_end THEN
    new_date := (p_period_end AT TIME ZONE 'Europe/London')::date - 1;
  ELSE
    new_date := NULL;
  END IF;

  IF m.cancel_effective_date IS NOT DISTINCT FROM new_date THEN
    RETURN jsonb_build_object('found', true, 'action', 'unchanged', 'cancel_effective_date', new_date);
  END IF;

  UPDATE customer_memberships SET cancel_effective_date = new_date, updated_at = now() WHERE id = m.id;
  RETURN jsonb_build_object(
    'found', true,
    'action', CASE WHEN new_date IS NULL THEN 'cancel_cleared' ELSE 'cancel_scheduled' END,
    'cancel_effective_date', new_date
  );
END $function$

CREATE OR REPLACE FUNCTION public.purge_api_idempotency()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  DELETE FROM api_idempotency WHERE created_at < now() - interval '7 days';
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.purge_parity_log()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  DELETE FROM parity_log WHERE at < now() - interval '30 days';
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.quote_booking(p_session_id uuid, p_customer_id uuid, p_party_size integer)
 RETURNS TABLE(seat_no integer, seat_kind text, band_id uuid, list_price numeric, unit_price numeric, credit_eligible boolean, membership_level text, discount_percent numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_band UUID;
  v_price NUMERIC;
  v_level TEXT;
  v_eligible BOOLEAN := false;
  v_discount NUMERIC := 0;
BEGIN
  IF p_party_size IS NULL OR p_party_size < 1 THEN
    RAISE EXCEPTION 'Party size must be at least 1';
  END IF;

  SELECT s.band_id INTO v_band
  FROM sessions s
  WHERE s.id = p_session_id AND s.type = 'public';

  IF v_band IS NULL THEN
    RAISE EXCEPTION 'Session % is not a public session with a band', p_session_id;
  END IF;

  SELECT b.price INTO v_price FROM session_bands b WHERE b.id = v_band;

  SELECT mp.level INTO v_level
  FROM customer_memberships cm
  JOIN membership_plans mp ON mp.id = cm.plan_id
  WHERE cm.customer_id = p_customer_id
    AND cm.subscription_status = 'active'
    AND (cm.cancel_effective_date IS NULL
         OR cm.cancel_effective_date >= (now() AT TIME ZONE 'Europe/London')::date)
    AND mp.level IS NOT NULL
  ORDER BY cm.created_at DESC
  LIMIT 1;

  IF v_level IS NOT NULL THEN
    SELECT t.credit_eligible, t.discount_percent
      INTO v_eligible, v_discount
    FROM membership_band_terms t
    WHERE t.membership_level = v_level AND t.band_id = v_band;

    v_eligible := COALESCE(v_eligible, false);
    v_discount := COALESCE(v_discount, 0);
  END IF;

  RETURN QUERY
  SELECT
    g,
    CASE WHEN g = 1 THEN 'account_holder' ELSE 'guest' END,
    v_band,
    v_price,
    CASE WHEN g = 1 THEN ROUND(v_price * (1 - v_discount / 100), 2) ELSE v_price END,
    (g = 1 AND v_eligible),
    CASE WHEN g = 1 THEN v_level ELSE NULL END,
    CASE WHEN g = 1 THEN v_discount ELSE 0::NUMERIC END
  FROM generate_series(1, p_party_size) AS g;
END;
$function$

CREATE OR REPLACE FUNCTION public.quote_event(p_event_id uuid, p_customer_id uuid, p_places integer, p_account_holder_attending boolean, p_new_membership_frequency text DEFAULT NULL::text)
 RETURNS TABLE(place_no integer, attendee_type text, price_level text, unit_price numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  e public.events%ROWTYPE;
  v_level text := public.event_member_level_with_new(p_customer_id, p_new_membership_frequency);
BEGIN
  IF p_places IS NULL OR p_places < 1 THEN RAISE EXCEPTION 'Places must be at least 1'; END IF;
  IF p_new_membership_frequency IS NOT NULL AND p_new_membership_frequency NOT IN ('monthly', 'yearly') THEN
    RAISE EXCEPTION 'Membership frequency must be monthly or yearly';
  END IF;
  SELECT * INTO e FROM public.events WHERE id = p_event_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Event % not found', p_event_id; END IF;
  IF e.price_public IS NULL OR e.price_pre_herd IS NULL OR e.price_herd IS NULL THEN
    RAISE EXCEPTION 'Event % has no prices set', p_event_id;
  END IF;
  RETURN QUERY
  SELECT g,
    CASE WHEN g = 1 AND p_account_holder_attending THEN 'account_holder' ELSE 'guest' END,
    CASE WHEN g = 1 AND p_account_holder_attending AND v_level IS NOT NULL THEN v_level ELSE 'public' END,
    CASE
      WHEN g = 1 AND p_account_holder_attending AND v_level = 'herd' THEN e.price_herd
      WHEN g = 1 AND p_account_holder_attending AND v_level = 'pre_herd' THEN e.price_pre_herd
      ELSE e.price_public
    END
  FROM generate_series(1, p_places) AS g;
END; $function$

CREATE OR REPLACE FUNCTION public.refresh_herd_flags()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  wait_months integer;
  changed integer;
begin
  select addon_credit_wait_months into wait_months from public.membership_settings where id;
  wait_months := coalesce(wait_months, 6);
  update public.customer_memberships cm
     set is_herd = (cm.billing_frequency = 'yearly'
                    or cm.start_date <= (now() at time zone 'Europe/London')::date - (wait_months || ' months')::interval),
         updated_at = now()
   where cm.herd_override is null
     and cm.is_herd is distinct from (cm.billing_frequency = 'yearly'
                    or cm.start_date <= (now() at time zone 'Europe/London')::date - (wait_months || ' months')::interval);
  get diagnostics changed = row_count;
  return changed;
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.run_membership_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p integer; s integer;
BEGIN
  p := public.allocate_membership_credit_periods();
  s := public.lapse_sweep_expired_bookings();
  RETURN jsonb_build_object('periods_created', p, 'lapsed_bookings_cancelled', s);
END $function$

CREATE OR REPLACE FUNCTION public.sessions_assign_band()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.band_id IS NULL THEN
      NEW.band_id := band_for_session_start(NEW.start_time);
    END IF;
  ELSIF NEW.start_time IS DISTINCT FROM OLD.start_time AND NOT NEW.band_overridden THEN
    NEW.band_id := band_for_session_start(NEW.start_time);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.store_credit_apply(p_customer_id uuid, p_amount numeric, p_reason text, p_order_id uuid DEFAULT NULL::uuid, p_booking_id uuid DEFAULT NULL::uuid, p_staff_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_gift_card_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_balance numeric; v_new numeric; v_txn uuid;
BEGIN
  IF p_amount IS NULL OR p_amount = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_required');
  END IF;
  SELECT store_credit_balance INTO v_balance FROM customers WHERE id = p_customer_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'customer_not_found');
  END IF;
  v_new := round(v_balance + p_amount, 2);
  IF v_new < 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_store_credit', 'balance', v_balance);
  END IF;
  UPDATE customers SET store_credit_balance = v_new, updated_at = now() WHERE id = p_customer_id;
  INSERT INTO store_credit_transactions (customer_id, amount, balance_after, reason, order_id, booking_id, gift_card_id, staff_id, note)
  VALUES (p_customer_id, round(p_amount,2), v_new, p_reason, p_order_id, p_booking_id, p_gift_card_id, p_staff_id, p_note)
  RETURNING id INTO v_txn;
  RETURN jsonb_build_object('ok', true, 'transaction_id', v_txn, 'balance', v_new);
END $function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
